const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Readex+Pro:wght@300;400;500;600;700&display=swap');
:root{
  --navy:#24336b; --navy-2:#2c4484; --navy-3:#1f2d5c; --navy-deep:#0e1d49;
  --gold:#c6972d; --gold-deep:#b27f2b; --gold-light:#f7de7c; --cream:#fff2d4; --cream-2:#fbf6e4;
  --green:#0ab0a2; --green-deep:#007066; --green-soft:#e9f5f6;
  --paper:#fffdf8; --card:#ffffff; --line:#e6e6f0; --search:#f5f7fb;
  --ink:#1c2547; --ink-2:#5b6284; --ink-3:#9298b4;
  --red:#a03a2e; --red-soft:#f9ebe8;
  --grad-navy:linear-gradient(135deg,#2c4484 0%,#24336b 45%,#0e1d49 100%);
  --grad-gold:linear-gradient(120deg,#f7de7c 0%,#c6972d 100%);
}
*{box-sizing:border-box;margin:0}
.cpa{min-height:100vh;background:var(--paper);color:var(--ink);
  font-family:'Readex Pro','Segoe UI',Tahoma,sans-serif;font-size:14px;line-height:1.7}
.cpa button{font:inherit;cursor:pointer;border:none;background:none;color:inherit}
.cpa input,.cpa textarea,.cpa select{font:inherit;color:var(--ink);width:100%;
  border:1px solid var(--line);border-radius:10px;padding:9px 13px;background:#fff;outline:none}
.cpa input:focus,.cpa textarea:focus,.cpa select:focus{border-color:var(--navy-2);box-shadow:0 0 0 3px rgba(44,68,132,.12)}
.topbar{background:#fff;padding:0 22px;display:flex;align-items:center;gap:16px;height:64px;
  position:sticky;top:0;z-index:20;border-bottom:1px solid var(--line)}
.topbar::after{content:"";position:absolute;left:0;right:0;bottom:-4px;height:4px;
  background:linear-gradient(-90deg,#0e1d49,#24336b,#2c4484,#c6972d)}
.logo-img{height:38px;display:block}
.brand-sep{width:1px;height:30px;background:var(--line)}
.brand-t{line-height:1.3}
.brand-t b{display:block;font-size:13.5px;color:var(--navy);font-weight:600}
.brand-t span{font-size:10.5px;color:var(--ink-3);letter-spacing:.14em}
.topbtn{display:flex;align-items:center;gap:7px;padding:7px 13px;border-radius:9px;
  background:var(--search);color:var(--navy);font-size:13px;font-weight:500;border:1px solid var(--line)}
.topbtn:hover{border-color:var(--navy-2);background:#eef1fa}
.rolechip{background:var(--grad-gold);color:var(--navy-deep);font-size:11px;font-weight:600;padding:2px 9px;border-radius:20px}
.shell{display:flex;max-width:1200px;margin:0 auto}
.nav{width:225px;flex-shrink:0;padding:20px 12px;position:sticky;top:68px;align-self:flex-start;height:calc(100vh - 68px);overflow:auto}
.nav button{display:flex;align-items:center;gap:10px;width:100%;padding:9px 13px;border-radius:10px;
  color:var(--ink-2);font-weight:500;font-size:13.5px;margin-bottom:3px;text-align:start}
.nav button:hover{background:var(--cream-2);color:var(--navy)}
.nav button.on{background:var(--grad-navy);color:#fff;box-shadow:0 4px 12px rgba(14,29,73,.22)}
.main{flex:1;padding:26px 26px 60px;min-width:0}
.pagehead{margin-bottom:20px}
.pagehead h1{font-size:21px;font-weight:700;color:var(--navy);display:flex;align-items:center;gap:10px}
.pagehead h1::before{content:"";width:0;height:0;border-block:7px solid transparent;
  border-inline-start:11px solid var(--gold);display:inline-block}
.pagehead p{color:var(--ink-2);font-size:13px;margin-top:3px;padding-inline-start:21px}
.hero{background:var(--grad-navy);border-radius:16px;padding:22px 26px;color:#fff;margin-bottom:20px;
  display:flex;align-items:center;gap:18px;position:relative;overflow:hidden}
.hero::before{content:"";position:absolute;inset-inline-end:-30px;top:-40px;width:200px;height:200px;
  background:linear-gradient(135deg,rgba(247,222,124,.16),transparent 60%);transform:rotate(45deg)}
.hero .mark{height:56px;filter:brightness(0) invert(1);opacity:.95;flex-shrink:0}
.hero h1{font-size:20px;font-weight:600}
.hero p{font-size:13px;color:var(--gold-light);margin-top:2px}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px 18px}
.tilegrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(232px,1fr));gap:14px}
.tile{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:18px;text-align:start;
  transition:.16s;display:block;width:100%;position:relative;overflow:hidden}
.tile::after{content:"";position:absolute;inset-inline-end:0;bottom:0;width:0;height:0;
  border-block-end:26px solid var(--cream);border-inline-start:26px solid transparent;opacity:0;transition:.16s}
.tile:hover{border-color:var(--gold);transform:translateY(-2px);box-shadow:0 8px 20px rgba(36,51,107,.12)}
.tile:hover::after{opacity:1}
.tile .ic{width:40px;height:40px;border-radius:11px;background:var(--cream);color:var(--gold-deep);
  display:flex;align-items:center;justify-content:center;margin-bottom:12px}
.tile b{display:block;font-size:14.5px;margin-bottom:3px;color:var(--navy);font-weight:600}
.tile span{font-size:12px;color:var(--ink-2)}
.tile .cnt{float:inline-end;background:var(--navy);color:var(--gold-light);font-size:12px;font-weight:600;padding:2px 10px;border-radius:20px}
.statrow{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:20px}
.stat{background:var(--grad-navy);color:#fff;border-radius:14px;padding:15px 17px;position:relative;overflow:hidden}
.stat::after{content:"";position:absolute;inset-inline-end:12px;top:14px;width:0;height:0;
  border-block:5px solid transparent;border-inline-start:8px solid var(--gold)}
.stat b{font-size:25px;display:block;color:var(--gold-light);font-weight:600}
.stat span{font-size:11.5px;opacity:.85}
.seclabel{font-size:12px;font-weight:600;color:var(--green-deep);margin-bottom:9px;
  display:flex;align-items:center;gap:6px}
.toolrow{display:flex;gap:10px;margin-bottom:15px;flex-wrap:wrap;align-items:center}
.searchbox{position:relative;flex:1;min-width:200px}
.searchbox svg{position:absolute;inset-inline-start:12px;top:10px;color:var(--ink-3)}
.searchbox input{padding-inline-start:38px;background:var(--search);border-color:transparent}
.searchbox input:focus{background:#fff;border-color:var(--navy-2)}
.btn{display:inline-flex;align-items:center;gap:7px;padding:9px 16px;border-radius:10px;font-weight:600;font-size:13px}
.btn.primary{background:var(--grad-navy);color:#fff;box-shadow:0 3px 10px rgba(14,29,73,.25)}
.btn.primary:hover{filter:brightness(1.12)}
.btn.gold{background:var(--grad-gold);color:var(--navy-deep)}
.btn.ghost{border:1px solid var(--line);background:#fff;color:var(--navy)}
.btn.ghost:hover{border-color:var(--gold);color:var(--gold-deep)}
.btn.sm{padding:5px 11px;font-size:12px;border-radius:8px}
.btn.danger{background:var(--red-soft);color:var(--red)}
.chip{font-size:11px;font-weight:600;padding:3px 10px;border-radius:20px;white-space:nowrap}
.chip.g{background:var(--green-soft);color:var(--green-deep)}
.chip.b{background:#edf1fb;color:var(--navy-2)}
.chip.y{background:var(--cream);color:var(--gold-deep)}
.chip.r{background:var(--red-soft);color:var(--red)}
.chip.n{background:#f0f0f4;color:var(--ink-2)}
.item{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:15px 18px;margin-bottom:11px}
.item h3{font-size:14.5px;font-weight:600;color:var(--navy)}
.item .meta{display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:11.5px;color:var(--ink-3);margin-top:6px}
.item p.body{margin-top:8px;color:var(--ink-2);font-size:13px;white-space:pre-wrap}
.rowtop{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}
.formcard{background:var(--cream-2);border:1px solid var(--gold-light);border-radius:14px;padding:17px 19px;margin-bottom:16px}
.formcard h3{font-size:13.5px;font-weight:600;color:var(--gold-deep);margin-bottom:11px;display:flex;align-items:center;gap:7px}
.formcard h3::before{content:"";width:0;height:0;border-block:5px solid transparent;border-inline-start:8px solid var(--gold)}
.fgrid{display:grid;gap:10px}
.fgrid.two{grid-template-columns:1fr 1fr}
.tabs{display:flex;gap:6px;margin-bottom:15px;border-bottom:1px solid var(--line);flex-wrap:wrap}
.tabs button{padding:8px 15px;font-weight:600;font-size:12.5px;color:var(--ink-2);border-bottom:2px solid transparent;margin-bottom:-1px}
.tabs button.on{color:var(--navy);border-color:var(--gold)}
.comment{border-inline-start:3px solid var(--line);padding:8px 15px;margin:10px 0}
.comment.staff{border-inline-start:3px solid var(--gold)}
.comment .who{font-size:12px;font-weight:600;color:var(--navy)}
.comment .who .chip{margin-inline-start:6px}
.comment p{font-size:13px;color:var(--ink-2);margin-top:2px;white-space:pre-wrap}
.faq-q{display:flex;justify-content:space-between;align-items:center;gap:10px;width:100%;text-align:start;
  font-weight:600;font-size:13.5px;padding:14px 2px;color:var(--navy)}
.faq-q svg{color:var(--gold-deep);flex-shrink:0}
.faq-a{color:var(--ink-2);font-size:13px;padding:0 2px 15px;white-space:pre-wrap}
.empty{text-align:center;padding:42px 20px;color:var(--ink-3)}
.empty svg{margin:0 auto 10px;display:block;opacity:.4}
.usertable{width:100%;border-collapse:collapse}
.usertable th{text-align:start;font-size:11.5px;color:var(--green-deep);font-weight:600;padding:8px 10px;border-bottom:1px solid var(--line)}
.usertable td{padding:10px;border-bottom:1px solid var(--line);font-size:13px}
.footer-note{text-align:center;color:var(--ink-3);font-size:11.5px;margin-top:36px}
.menu-pop{position:absolute;top:54px;inset-inline-end:0;background:#fff;border:1px solid var(--line);border-radius:14px;
  box-shadow:0 14px 34px rgba(14,29,73,.16);padding:8px;z-index:50;min-width:260px;color:var(--ink)}
.menu-pop button{display:block;width:100%;text-align:start;padding:9px 13px;border-radius:9px;font-size:13px}
.menu-pop button:hover{background:var(--cream-2)}
.menu-pop .lbl{font-size:10.5px;color:var(--gold-deep);font-weight:600;padding:6px 13px 3px}
@media(max-width:860px){
  .shell{flex-direction:column}
  .nav{width:100%;height:auto;position:static;display:flex;overflow-x:auto;padding:10px 12px;gap:4px;border-bottom:1px solid var(--line);background:var(--card)}
  .nav button{width:auto;white-space:nowrap;margin:0}
  .main{padding:18px 14px 50px}
  .fgrid.two{grid-template-columns:1fr}
  .brand-t{display:none}
  .logo-img{height:32px}
  .hero .mark{display:none}
}
`;

