/* ------------------------------------------------------------------ */
/* التخزين                                                             */
/* ------------------------------------------------------------------ */
const KEY = "cpa_planning_ar_v1";
async function loadStored() {
  try {
    if (typeof window !== "undefined" && window.storage) {
      const r = await window.storage.get(KEY);
      if (r && r.value) return JSON.parse(r.value);
    }
  } catch (e) { /* لا توجد بيانات محفوظة بعد */ }
  return null;
}
async function persist(data) {
  try {
    if (typeof window !== "undefined" && window.storage) {
      await window.storage.set(KEY, JSON.stringify(data));
    }
  } catch (e) { /* التخزين غير متاح */ }
}

const uid = () => Math.random().toString(36).slice(2, 9) + Date.now().toString(36);
const today = () => new Date().toISOString().slice(0, 10);
const StatusChip = ({ kind, label }) => <span className={`chip ${kind}`}>{label}</span>;
const Empty = () => <div className="empty"><FileText size={30} /><p>{t.noResults}</p></div>;

/* ------------------------------------------------------------------ */
/* التطبيق                                                             */
/* ------------------------------------------------------------------ */
export default function App() {
  const [userId, setUserId] = useState("u1");
  const [view, setView] = useState("dashboard");
  const [openDisc, setOpenDisc] = useState(null);
  const [data, setData] = useState(seedData);
  const [menu, setMenu] = useState(false);
  const [loaded, setLoaded] = useState(false);

  const me = data.users.find((u) => u.id === userId) || data.users[0];
  const canManage = me.role === "officer" || me.role === "manager";
  const isAdmin = me.role === "admin";
  const roleLabel = { employee: t.roleEmployee, officer: t.roleOfficer, manager: t.roleManager, admin: t.roleAdmin };

  useEffect(() => {
    loadStored().then((d) => { if (d && d.announcements) setData(d); setLoaded(true); });
  }, []);
  useEffect(() => { if (loaded) persist(data); }, [data, loaded]);

  const update = (fn) => setData((d) => fn(structuredClone(d)));
  const userName = (id) => data.users.find((x) => x.id === id)?.name || "—";
  const isStaff = (id) => ["officer", "manager"].includes(data.users.find((u) => u.id === id)?.role);

  const NAV = [
    { id: "dashboard", icon: LayoutGrid, label: t.dashboard },
    { id: "announcements", icon: Megaphone, label: t.announcements },
    { id: "discussions", icon: MessagesSquare, label: t.discussions },
    { id: "inquiries", icon: MailQuestion, label: t.inquiries },
    { id: "knowledge", icon: BookOpen, label: t.knowledge },
    { id: "faq", icon: HelpCircle, label: t.faq },
    { id: "suggestions", icon: Lightbulb, label: t.suggestions },
    ...(isAdmin ? [{ id: "admin", icon: Users, label: t.admin }] : []),
  ];
  const go = (v) => { setView(v); setOpenDisc(null); setMenu(false); };

  return (
    <div className="cpa" dir="rtl" lang="ar">
      <style>{CSS}</style>

      <header className="topbar">
        <img className="logo-img" src={LOGO_FULL} alt={t.org} />
        <div className="brand-sep" />
        <div className="brand-t"><b>{t.app}</b><span>HEMA</span></div>
        <div style={{ flex: 1 }} />
        <div style={{ position: "relative" }}>
          <button className="topbtn" onClick={() => setMenu(!menu)}>
            {userName(me.id)} <span className="rolechip">{roleLabel[me.role]}</span>
          </button>
          {menu && (
            <div className="menu-pop">
              <div className="lbl">{t.switchUser}</div>
              {data.users.filter((u) => u.active).map((u) => (
                <button key={u.id} onClick={() => { setUserId(u.id); setMenu(false); go("dashboard"); }}>
                  {u.name}
                  <span className="chip n" style={{ marginInlineStart: 8 }}>{roleLabel[u.role]}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      </header>

      <div className="shell">
        <nav className="nav">
          {NAV.map((n) => (
            <button key={n.id} className={view === n.id ? "on" : ""} onClick={() => go(n.id)}>
              <n.icon size={17} /><span>{n.label}</span>
            </button>
          ))}
        </nav>

        <main className="main">
          {view === "dashboard" && <Dashboard {...{ me, data, go, canManage, userName }} />}
          {view === "announcements" && <Announcements {...{ me, data, update, canManage, userName }} />}
          {view === "discussions" && !openDisc && <Discussions {...{ me, data, update, canManage, userName, setOpenDisc }} />}
          {view === "discussions" && openDisc && <DiscussionDetail {...{ me, data, update, canManage, userName, isStaff, roleLabel, id: openDisc, close: () => setOpenDisc(null) }} />}
          {view === "inquiries" && <Inquiries {...{ me, data, update, canManage, userName }} />}
          {view === "knowledge" && <Knowledge {...{ data, update, canManage }} />}
          {view === "faq" && <Faq {...{ data, update, canManage }} />}
          {view === "suggestions" && <Suggestions {...{ me, data, update, canManage, userName }} />}
          {view === "admin" && isAdmin && <Admin {...{ data, update, roleLabel }} />}
          <p className="footer-note">{t.footer}</p>
        </main>
      </div>
    </div>
  );
}

/* ================= لوحة التحكم ================= */
function Dashboard({ me, data, go, canManage, userName }) {
  const tiles = [
    { id: "announcements", icon: Megaphone, cnt: data.announcements.filter((a) => !a.archived).length },
    { id: "discussions", icon: MessagesSquare, cnt: data.discussions.filter((d) => d.status === "open").length },
    { id: "inquiries", icon: MailQuestion, cnt: data.inquiries.filter((q) => q.status !== "resolved" && (canManage || q.user === me.id)).length },
    { id: "knowledge", icon: BookOpen, cnt: data.documents.length },
    { id: "faq", icon: HelpCircle, cnt: data.faqs.length },
    { id: "suggestions", icon: Lightbulb, cnt: data.suggestions.filter((s) => s.status === "ssNew" || s.user === me.id).length },
  ];
  const labels = { announcements: t.announcements, discussions: t.discussions, inquiries: t.inquiries, knowledge: t.knowledge, faq: t.faq, suggestions: t.suggestions };
  return (
    <>
      <div className="hero">
        <img className="mark" src={LOGO_MARK} alt="" />
        <div>
          <h1>{t.welcome}، {userName(me.id)}</h1>
          <p>{t.dashSub}</p>
        </div>
      </div>
      {me.role === "manager" && (
        <>
          <p className="seclabel"><BarChart3 size={14} />{t.managerView}</p>
          <div className="statrow">
            <div className="stat"><b>{data.inquiries.filter((q) => q.status === "open").length}</b><span>{t.statOpenInq}</span></div>
            <div className="stat"><b>{data.suggestions.filter((s) => s.status === "ssNew").length}</b><span>{t.statNewSug}</span></div>
            <div className="stat"><b>{data.discussions.filter((d) => d.status === "open").length}</b><span>{t.statActiveDisc}</span></div>
            <div className="stat"><b>{data.documents.length}</b><span>{t.statDocs}</span></div>
          </div>
        </>
      )}
      <div className="tilegrid">
        {tiles.map((x) => (
          <button key={x.id} className="tile" onClick={() => go(x.id)}>
            <span className="cnt">{x.cnt}</span>
            <span className="ic"><x.icon size={19} /></span>
            <b>{labels[x.id]}</b>
            <span>{t.dashTiles[x.id]}</span>
          </button>
        ))}
      </div>
    </>
  );
}

/* ================= الإعلانات ================= */
function Announcements({ me, data, update, canManage, userName }) {
  const [tab, setTab] = useState("active");
  const [q, setQ] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [f, setF] = useState({ title: "", body: "", cat: "catAnnouncement" });

  const catChip = { catAnnouncement: "b", catUpdate: "g", catCircular: "y", catDeadline: "r" };
  const list = data.announcements
    .filter((a) => (tab === "active" ? !a.archived : a.archived))
    .filter((a) => (a.title + a.body).includes(q))
    .sort((a, b) => b.date.localeCompare(a.date));

  const publish = () => {
    if (!f.title.trim() || !f.body.trim()) return alert(t.required);
    update((d) => { d.announcements.unshift({ id: uid(), ...f, date: today(), author: me.id, archived: false }); return d; });
    setF({ title: "", body: "", cat: "catAnnouncement" }); setShowForm(false);
  };
  const toggleArchive = (id) => update((d) => { const a = d.announcements.find((x) => x.id === id); a.archived = !a.archived; return d; });

  return (
    <>
      <div className="pagehead"><h1>{t.announcements}</h1></div>
      <div className="toolrow">
        <div className="searchbox"><Search size={16} /><input placeholder={t.search} value={q} onChange={(e) => setQ(e.target.value)} /></div>
        {canManage && <button className="btn primary" onClick={() => setShowForm(!showForm)}><Plus size={15} />{t.newAnnouncement}</button>}
      </div>
      {showForm && (
        <div className="formcard">
          <h3>{t.newAnnouncement}</h3>
          <div className="fgrid">
            <div className="fgrid two">
              <input placeholder={t.title} value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} />
              <select value={f.cat} onChange={(e) => setF({ ...f, cat: e.target.value })}>
                {["catAnnouncement", "catUpdate", "catCircular", "catDeadline"].map((c) => <option key={c} value={c}>{t[c]}</option>)}
              </select>
            </div>
            <textarea rows={3} placeholder={t.content} value={f.body} onChange={(e) => setF({ ...f, body: e.target.value })} />
            <div style={{ display: "flex", gap: 8 }}>
              <button className="btn primary" onClick={publish}><Send size={14} />{t.publish}</button>
              <button className="btn ghost" onClick={() => setShowForm(false)}>{t.cancel}</button>
            </div>
          </div>
        </div>
      )}
      <div className="tabs">
        <button className={tab === "active" ? "on" : ""} onClick={() => setTab("active")}>{t.active}</button>
        <button className={tab === "archived" ? "on" : ""} onClick={() => setTab("archived")}>{t.archived}</button>
      </div>
      {list.length === 0 && <Empty />}
      {list.map((a) => (
        <div className="item" key={a.id}>
          <div className="rowtop">
            <div>
              <h3>{a.title}</h3>
              <div className="meta">
                <StatusChip kind={catChip[a.cat]} label={t[a.cat]} />
                <span><Clock size={12} style={{ verticalAlign: "-2px" }} /> {a.date}</span>
                <span>{t.by} {userName(a.author)}</span>
              </div>
            </div>
            {canManage && (
              <button className="btn ghost sm" onClick={() => toggleArchive(a.id)}>
                {a.archived ? <><ArchiveRestore size={13} />{t.restore}</> : <><Archive size={13} />{t.archive}</>}
              </button>
            )}
          </div>
          <p className="body">{a.body}</p>
        </div>
      ))}
    </>
  );
}

/* ================= النقاشات ================= */
function Discussions({ me, data, update, canManage, userName, setOpenDisc }) {
  const [showForm, setShowForm] = useState(false);
  const [f, setF] = useState({ title: "", desc: "" });
  const create = () => {
    if (!f.title.trim()) return alert(t.required);
    update((d) => { d.discussions.unshift({ id: uid(), ...f, status: "open", date: today(), author: me.id, comments: [] }); return d; });
    setF({ title: "", desc: "" }); setShowForm(false);
  };
  return (
    <>
      <div className="pagehead"><h1>{t.discussions}</h1></div>
      {canManage && (
        <div className="toolrow">
          <div style={{ flex: 1 }} />
          <button className="btn primary" onClick={() => setShowForm(!showForm)}><Plus size={15} />{t.newTopic}</button>
        </div>
      )}
      {showForm && (
        <div className="formcard">
          <h3>{t.newTopic}</h3>
          <div className="fgrid">
            <input placeholder={t.title} value={f.title} onChange={(e) => setF({ ...f, title: e.target.value })} />
            <textarea rows={2} placeholder={t.description} value={f.desc} onChange={(e) => setF({ ...f, desc: e.target.value })} />
            <div style={{ display: "flex", gap: 8 }}>
              <button className="btn primary" onClick={create}>{t.createTopic}</button>
              <button className="btn ghost" onClick={() => setShowForm(false)}>{t.cancel}</button>
            </div>
          </div>
        </div>
      )}
      {data.discussions.length === 0 && <Empty />}
      {data.discussions.map((d) => (
        <div className="item" key={d.id} style={{ cursor: "pointer" }} onClick={() => setOpenDisc(d.id)}>
          <div className="rowtop">
            <div>
              <h3>{d.title}</h3>
              <div className="meta">
                <StatusChip kind={d.status === "open" ? "g" : "n"} label={d.status === "open" ? t.open : t.closed} />
                <span>{d.date}</span>
                <span>{t.by} {userName(d.author)}</span>
                <span><MessagesSquare size={12} style={{ verticalAlign: "-2px" }} /> {d.comments.length} {t.replies}</span>
              </div>
            </div>
          </div>
          <p className="body">{d.desc}</p>
        </div>
      ))}
    </>
  );
}

function DiscussionDetail({ me, data, update, canManage, userName, isStaff, roleLabel, id, close }) {
  const d = data.discussions.find((x) => x.id === id);
  const [reply, setReply] = useState("");
  if (!d) return null;
  const post = () => {
    if (!reply.trim()) return;
    update((s) => { s.discussions.find((x) => x.id === id).comments.push({ id: uid(), user: me.id, text: reply, date: today() }); return s; });
    setReply("");
  };
  const toggle = () => update((s) => { const x = s.discussions.find((y) => y.id === id); x.status = x.status === "open" ? "closed" : "open"; return s; });
  const removeComment = (cid) => update((s) => { const x = s.discussions.find((y) => y.id === id); x.comments = x.comments.filter((c) => c.id !== cid); return s; });

  return (
    <>
      <button className="btn ghost sm" onClick={close} style={{ marginBottom: 14 }}><ArrowRight size={14} />{t.back}</button>
      <div className="card">
        <div className="rowtop">
          <div>
            <h3 style={{ fontSize: 17, fontWeight: 600, color: "var(--navy)" }}>{d.title}</h3>
            <div style={{ marginTop: 6, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", fontSize: 12, color: "var(--ink-3)" }}>
              <StatusChip kind={d.status === "open" ? "g" : "n"} label={d.status === "open" ? t.open : t.closed} />
              <span>{d.date}</span><span>{t.by} {userName(d.author)}</span>
            </div>
          </div>
          {canManage && (
            <button className="btn ghost sm" onClick={toggle}>
              <Lock size={13} />{d.status === "open" ? t.closeDiscussion : t.reopen}
            </button>
          )}
        </div>
        <p style={{ marginTop: 10, color: "var(--ink-2)", fontSize: 13, whiteSpace: "pre-wrap" }}>{d.desc}</p>

        <div style={{ marginTop: 18, borderTop: "1px solid var(--line)", paddingTop: 10 }}>
          {d.comments.map((c) => (
            <div className={`comment ${isStaff(c.user) ? "staff" : ""}`} key={c.id}>
              <div className="rowtop">
                <div className="who">
                  {userName(c.user)}
                  {isStaff(c.user) && <span className="chip y">{roleLabel[data.users.find((u) => u.id === c.user)?.role]}</span>}
                  <span style={{ color: "var(--ink-3)", fontWeight: 400, marginInlineStart: 8, fontSize: 12 }}>{c.date}</span>
                </div>
                {canManage && <button className="btn danger sm" onClick={() => removeComment(c.id)}><Trash2 size={13} /></button>}
              </div>
              <p>{c.text}</p>
            </div>
          ))}
          {d.status === "open" ? (
            <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
              <input placeholder={t.writeReply} value={reply} onChange={(e) => setReply(e.target.value)} onKeyDown={(e) => e.key === "Enter" && post()} />
              <button className="btn primary" onClick={post}><Send size={14} />{t.post}</button>
            </div>
          ) : (
            <p style={{ marginTop: 14, fontSize: 13, color: "var(--ink-3)" }}><Lock size={13} style={{ verticalAlign: "-2px" }} /> {t.discussionClosed}</p>
          )}
        </div>
      </div>
    </>
  );
}

/* ================= الاستفسارات ================= */
function Inquiries({ me, data, update, canManage, userName }) {
  const [f, setF] = useState({ subject: "", details: "" });
  const [respTo, setRespTo] = useState(null);
  const [resp, setResp] = useState("");

  const list = data.inquiries
    .filter((q) => canManage || q.user === me.id)
    .sort((a, b) => b.date.localeCompare(a.date));
  const stChip = { open: ["y", t.stOpen], answered: ["b", t.stAnswered], resolved: ["g", t.stResolved] };

  const submit = () => {
    if (!f.subject.trim() || !f.details.trim()) return alert(t.required);
    update((d) => { d.inquiries.unshift({ id: uid(), user: me.id, ...f, status: "open", date: today(), response: "", responder: null }); return d; });
    setF({ subject: "", details: "" });
  };
  const sendResponse = (id) => {
    if (!resp.trim()) return;
    update((d) => { const q = d.inquiries.find((x) => x.id === id); q.response = resp; q.responder = me.id; q.status = "answered"; return d; });
    setResp(""); setRespTo(null);
  };
  const resolve = (id) => update((d) => { d.inquiries.find((x) => x.id === id).status = "resolved"; return d; });

  return (
    <>
      <div className="pagehead"><h1>{t.inquiries}</h1><p>{canManage ? t.allInquiries : t.myInquiries}</p></div>
      {!canManage && (
        <div className="formcard">
          <h3>{t.newInquiry}</h3>
          <div className="fgrid">
            <input placeholder={t.subject} value={f.subject} onChange={(e) => setF({ ...f, subject: e.target.value })} />
            <textarea rows={3} placeholder={t.details} value={f.details} onChange={(e) => setF({ ...f, details: e.target.value })} />
            <div><button className="btn primary" onClick={submit}><Send size={14} />{t.submit}</button></div>
          </div>
        </div>
      )}
      {list.length === 0 && <Empty />}
      {list.map((q) => (
        <div className="item" key={q.id}>
          <div className="rowtop">
            <div>
              <h3>{q.subject}</h3>
              <div className="meta">
                <StatusChip kind={stChip[q.status][0]} label={stChip[q.status][1]} />
                <span>{q.date}</span>
                {canManage && <span>{t.by} {userName(q.user)}</span>}
              </div>
            </div>
            {canManage && q.status !== "resolved" && (
              <div style={{ display: "flex", gap: 6 }}>
                <button className="btn ghost sm" onClick={() => { setRespTo(respTo === q.id ? null : q.id); setResp(q.response); }}><Pencil size={13} />{t.respond}</button>
                {q.status === "answered" && <button className="btn gold sm" onClick={() => resolve(q.id)}><CheckCircle2 size={13} />{t.markResolved}</button>}
              </div>
            )}
          </div>
          <p className="body">{q.details}</p>
          {q.response && (
            <div className="comment staff" style={{ marginTop: 10 }}>
              <div className="who">{t.response}{q.responder && <span style={{ color: "var(--ink-3)", fontWeight: 400, marginInlineStart: 8, fontSize: 12 }}>{userName(q.responder)}</span>}</div>
              <p>{q.response}</p>
            </div>
          )}
          {respTo === q.id && (
            <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
              <input placeholder={t.writeResponse} value={resp} onChange={(e) => setResp(e.target.value)} />
              <button className="btn primary sm" onClick={() => sendResponse(q.id)}><Send size={13} />{t.post}</button>
            </div>
          )}
        </div>
      ))}
    </>
  );
}

/* ================= قاعدة المعرفة ================= */
function Knowledge({ data, update, canManage }) {
  const cats = ["manuals", "guidelines", "kpi", "policies", "templates", "other"];
  const [cat, setCat] = useState("all");
  const [q, setQ] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [f, setF] = useState({ name: "", cat: "manuals", desc: "" });

  const list = data.documents
    .filter((d) => cat === "all" || d.cat === cat)
    .filter((d) => (d.name + d.desc).includes(q));

  const add = () => {
    if (!f.name.trim()) return alert(t.required);
    update((d) => { d.documents.unshift({ id: uid(), ...f, date: today() }); return d; });
    setF({ name: "", cat: "manuals", desc: "" }); setShowForm(false);
  };
  const remove = (id) => update((d) => { d.documents = d.documents.filter((x) => x.id !== id); return d; });
  const download = (doc) => {
    const blob = new Blob(["\ufeff" + `${doc.name}\n${t[doc.cat]} — ${doc.date}\n\n${doc.desc}\n\n(ملف تجريبي أُنشئ من المنصة التجريبية.)`], { type: "text/plain;charset=utf-8" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = doc.name.replace(/\s+/g, "_") + ".txt";
    a.click();
    URL.revokeObjectURL(a.href);
  };

  return (
    <>
      <div className="pagehead"><h1>{t.knowledge}</h1></div>
      <div className="toolrow">
        <div className="searchbox"><Search size={16} /><input placeholder={t.search} value={q} onChange={(e) => setQ(e.target.value)} /></div>
        <select style={{ width: "auto" }} value={cat} onChange={(e) => setCat(e.target.value)}>
          <option value="all">{t.allCats}</option>
          {cats.map((c) => <option key={c} value={c}>{t[c]}</option>)}
        </select>
        {canManage && <button className="btn primary" onClick={() => setShowForm(!showForm)}><Plus size={15} />{t.addDocument}</button>}
      </div>
      {showForm && (
        <div className="formcard">
          <h3>{t.addDocument}</h3>
          <div className="fgrid">
            <div className="fgrid two">
              <input placeholder={t.docName} value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} />
              <select value={f.cat} onChange={(e) => setF({ ...f, cat: e.target.value })}>
                {cats.map((c) => <option key={c} value={c}>{t[c]}</option>)}
              </select>
            </div>
            <input placeholder={t.description} value={f.desc} onChange={(e) => setF({ ...f, desc: e.target.value })} />
            <div style={{ display: "flex", gap: 8 }}>
              <button className="btn primary" onClick={add}>{t.save}</button>
              <button className="btn ghost" onClick={() => setShowForm(false)}>{t.cancel}</button>
            </div>
          </div>
        </div>
      )}
      {list.length === 0 && <Empty />}
      {list.map((doc) => (
        <div className="item" key={doc.id}>
          <div className="rowtop">
            <div>
              <h3>{doc.name}</h3>
              <div className="meta"><StatusChip kind="g" label={t[doc.cat]} /><span>{doc.date}</span></div>
              <p className="body">{doc.desc}</p>
            </div>
            <div style={{ display: "flex", gap: 6, flexShrink: 0 }}>
              <button className="btn ghost sm" onClick={() => download(doc)}><Download size={13} />{t.download}</button>
              {canManage && <button className="btn danger sm" onClick={() => remove(doc.id)}><Trash2 size={13} /></button>}
            </div>
          </div>
        </div>
      ))}
    </>
  );
}

/* ================= الأسئلة الشائعة ================= */
function Faq({ data, update, canManage }) {
  const [open, setOpen] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId] = useState(null);
  const [f, setF] = useState({ q: "", a: "" });

  const save = () => {
    if (!f.q.trim() || !f.a.trim()) return alert(t.required);
    update((d) => {
      if (editId) { const x = d.faqs.find((y) => y.id === editId); x.q = f.q; x.a = f.a; }
      else d.faqs.push({ id: uid(), ...f });
      return d;
    });
    setF({ q: "", a: "" }); setShowForm(false); setEditId(null);
  };
  const startEdit = (x) => { setF({ q: x.q, a: x.a }); setEditId(x.id); setShowForm(true); };
  const remove = (id) => update((d) => { d.faqs = d.faqs.filter((x) => x.id !== id); return d; });

  return (
    <>
      <div className="pagehead"><h1>{t.faq}</h1></div>
      {canManage && (
        <div className="toolrow">
          <div style={{ flex: 1 }} />
          <button className="btn primary" onClick={() => { setShowForm(!showForm); setEditId(null); setF({ q: "", a: "" }); }}><Plus size={15} />{t.addFaq}</button>
        </div>
      )}
      {showForm && (
        <div className="formcard">
          <h3>{editId ? t.edit : t.addFaq}</h3>
          <div className="fgrid">
            <input placeholder={t.question} value={f.q} onChange={(e) => setF({ ...f, q: e.target.value })} />
            <textarea rows={2} placeholder={t.answer} value={f.a} onChange={(e) => setF({ ...f, a: e.target.value })} />
            <div style={{ display: "flex", gap: 8 }}>
              <button className="btn primary" onClick={save}>{t.save}</button>
              <button className="btn ghost" onClick={() => { setShowForm(false); setEditId(null); }}>{t.cancel}</button>
            </div>
          </div>
        </div>
      )}
      <div className="card" style={{ padding: "4px 18px" }}>
        {data.faqs.length === 0 && <Empty />}
        {data.faqs.map((x, i) => (
          <div key={x.id} style={{ borderBottom: i < data.faqs.length - 1 ? "1px solid var(--line)" : "none" }}>
            <button className="faq-q" onClick={() => setOpen(open === x.id ? null : x.id)}>
              {x.q}{open === x.id ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
            </button>
            {open === x.id && (
              <div className="faq-a">
                {x.a}
                {canManage && (
                  <div style={{ display: "flex", gap: 6, marginTop: 10 }}>
                    <button className="btn ghost sm" onClick={() => startEdit(x)}><Pencil size={13} />{t.edit}</button>
                    <button className="btn danger sm" onClick={() => remove(x.id)}><Trash2 size={13} />{t.delete}</button>
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </>
  );
}

/* ================= المقترحات ================= */
function Suggestions({ me, data, update, canManage, userName }) {
  const cats = ["sgImprove", "sgInitiative", "sgProcess", "sgFeedback"];
  const statuses = ["ssNew", "ssReview", "ssAccepted", "ssRejected", "ssImplemented"];
  const stChip = { ssNew: "n", ssReview: "y", ssAccepted: "g", ssRejected: "r", ssImplemented: "b" };
  const [f, setF] = useState({ cat: "sgImprove", text: "" });
  const [fbFor, setFbFor] = useState(null);
  const [fb, setFb] = useState("");

  const list = data.suggestions
    .filter((s) => canManage || s.user === me.id)
    .sort((a, b) => b.date.localeCompare(a.date));

  const submit = () => {
    if (!f.text.trim()) return alert(t.required);
    update((d) => { d.suggestions.unshift({ id: uid(), user: me.id, ...f, status: "ssNew", date: today(), feedback: "" }); return d; });
    setF({ cat: "sgImprove", text: "" });
  };
  const setStatus = (id, st) => update((d) => { d.suggestions.find((x) => x.id === id).status = st; return d; });
  const saveFb = (id) => { update((d) => { d.suggestions.find((x) => x.id === id).feedback = fb; return d; }); setFbFor(null); setFb(""); };

  return (
    <>
      <div className="pagehead"><h1>{t.suggestions}</h1><p>{canManage ? t.allSuggestions : t.mySuggestions}</p></div>
      {!canManage && (
        <div className="formcard">
          <h3>{t.newSuggestion}</h3>
          <div className="fgrid">
            <select value={f.cat} onChange={(e) => setF({ ...f, cat: e.target.value })}>
              {cats.map((c) => <option key={c} value={c}>{t[c]}</option>)}
            </select>
            <textarea rows={3} placeholder={t.details} value={f.text} onChange={(e) => setF({ ...f, text: e.target.value })} />
            <div><button className="btn primary" onClick={submit}><Send size={14} />{t.submit}</button></div>
          </div>
        </div>
      )}
      {list.length === 0 && <Empty />}
      {list.map((s) => (
        <div className="item" key={s.id}>
          <div className="rowtop">
            <div>
              <div className="meta" style={{ marginTop: 0 }}>
                <StatusChip kind={stChip[s.status]} label={t[s.status]} />
                <StatusChip kind="n" label={t[s.cat]} />
                <span>{s.date}</span>
                {canManage && <span>{t.by} {userName(s.user)}</span>}
              </div>
              <p className="body">{s.text}</p>
            </div>
            {canManage && (
              <select style={{ width: "auto", flexShrink: 0 }} value={s.status} onChange={(e) => setStatus(s.id, e.target.value)}>
                {statuses.map((st) => <option key={st} value={st}>{t[st]}</option>)}
              </select>
            )}
          </div>
          {s.feedback && (
            <div className="comment staff" style={{ marginTop: 8 }}>
              <div className="who">{t.feedback}</div><p>{s.feedback}</p>
            </div>
          )}
          {canManage && (
            fbFor === s.id ? (
              <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
                <input placeholder={t.writeFeedback} value={fb} onChange={(e) => setFb(e.target.value)} />
                <button className="btn primary sm" onClick={() => saveFb(s.id)}>{t.saveFeedback}</button>
                <button className="btn ghost sm" onClick={() => setFbFor(null)}><X size={13} /></button>
              </div>
            ) : (
              <button className="btn ghost sm" style={{ marginTop: 10 }} onClick={() => { setFbFor(s.id); setFb(s.feedback || ""); }}>
                <Pencil size={13} />{t.feedback}
              </button>
            )
          )}
        </div>
      ))}
    </>
  );
}

/* ================= إدارة المستخدمين ================= */
function Admin({ data, update, roleLabel }) {
  const [f, setF] = useState({ name: "", role: "employee" });
  const add = () => {
    if (!f.name.trim()) return alert(t.required);
    update((d) => { d.users.push({ id: uid(), name: f.name, role: f.role, active: true }); return d; });
    setF({ name: "", role: "employee" });
  };
  const setRole = (id, role) => update((d) => { d.users.find((u) => u.id === id).role = role; return d; });
  const toggleActive = (id) => update((d) => { const u = d.users.find((x) => x.id === id); u.active = !u.active; return d; });

  return (
    <>
      <div className="pagehead"><h1>{t.admin}</h1></div>
      <div className="formcard">
        <h3>{t.addUser}</h3>
        <div className="fgrid two">
          <input placeholder={t.name} value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} />
          <div style={{ display: "flex", gap: 8 }}>
            <select value={f.role} onChange={(e) => setF({ ...f, role: e.target.value })}>
              {["employee", "officer", "manager", "admin"].map((r) => <option key={r} value={r}>{roleLabel[r]}</option>)}
            </select>
            <button className="btn primary" onClick={add}><Plus size={14} />{t.addUser}</button>
          </div>
        </div>
      </div>
      <div className="card" style={{ overflowX: "auto" }}>
        <table className="usertable">
          <thead><tr><th>{t.name}</th><th>{t.role}</th><th>{t.status}</th><th>{t.actions}</th></tr></thead>
          <tbody>
            {data.users.map((u) => (
              <tr key={u.id}>
                <td>{u.name}</td>
                <td>
                  <select style={{ width: "auto", padding: "4px 8px" }} value={u.role} onChange={(e) => setRole(u.id, e.target.value)}>
                    {["employee", "officer", "manager", "admin"].map((r) => <option key={r} value={r}>{roleLabel[r]}</option>)}
                  </select>
                </td>
                <td><StatusChip kind={u.active ? "g" : "r"} label={u.active ? t.activeU : t.inactive} /></td>
                <td>
                  <button className={`btn sm ${u.active ? "danger" : "ghost"}`} onClick={() => toggleActive(u.id)}>
                    {u.active ? t.deactivate : t.activate}
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}
